// Reload the app while preserving localStorage and hash state.
reload() {
  // Snapshot current state
  const ls = this.window.localStorage;
  const saved = {};
  for (let i = 0; i < ls.length; i++) {
    const k = ls.key(i);
    saved[k] = ls.getItem(k);
  }
  const hash = this.window.location.hash;

  this.disposeApp();
  this.loadApp();

  // Restore state into the new window
  const newLs = this.window.localStorage;
  for (const k of Object.keys(saved)) {
    newLs.setItem(k, saved[k]);
  }

  // Restore hash — the app will re-read state from localStorage
  if (hash && hash !== '#/') {
    this.window.location.hash = hash;
    this.window.dispatchEvent(new this.window.Event('hashchange'));
  }
}

