reload() {
  // Snapshot current state
  const ls = this.window.localStorage;
  const saved = {};
  for (let i = 0; i < ls.length; i++) {
    const k = ls.key(i);
    saved[k] = ls.getItem(k);
  }
  const hash = this.window.location.hash;

  this.disposeApp();

  // Create new window and restore localStorage BEFORE the app initializes
  const indexPath = path.join(ROOT, 'index.html');
  const appPath = path.join(ROOT, 'js', 'app.js');
  if (!fs.existsSync(indexPath))
    throw new Error('verification support: ' + indexPath + ' does not exist');
  if (!fs.existsSync(appPath))
    throw new Error('verification support: ' + appPath + ' does not exist');
  const appSource = fs.readFileSync(appPath, 'utf8');
  if (appSource.trim().length === 0)
    throw new Error('verification support: ' + appPath + ' is empty');

  this.window = new Window({
    url: 'http://localhost/',
    settings: { disableJavaScriptFileLoading: true },
  });
  this.document = this.window.document;

  // Restore localStorage BEFORE app code runs
  const newLs = this.window.localStorage;
  for (const k of Object.keys(saved)) {
    newLs.setItem(k, saved[k]);
  }

  // Load the page and execute the app with preserved state
  this.document.write(fs.readFileSync(indexPath, 'utf8'));
  this.document.close();

  // Restore hash
  if (hash && hash !== '#/') {
    this.window.location.hash = hash;
    this.window.dispatchEvent(new this.window.Event('hashchange'));
  }
}

